'use strict';

/**
* LAPACK routine to reduce a general real `M-by-N` matrix `A` to upper or lower bi-diagonal form `B` by an orthogonal transformation `Q**T * A * P = B`.
*
* @module @stdlib/lapack/base/dgebrd
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dgebrd = require( '@stdlib/lapack/base/dgebrd' );
*
* var A = new Float64Array( [ 4.0, -1.0, 2.5, 7.0, 8.5, -2.0 ] );
* var D = new Float64Array( [ 0.0, 0.0 ] );
* var E = new Float64Array( [ 0.0 ] );
* var TAUQ = new Float64Array( [ 0.0, 0.0 ] );
* var TAUP = new Float64Array( [ 0.0, 0.0 ] );
* var WORK = new Float64Array( 100 );
*
* dgebrd( 'column-major', 3, 2, A, 3, D, E, TAUQ, TAUP, WORK, 100 );
* // A => <Float64Array>[ ~-4.822, ~-0.113, ~0.283, ~-3.007, ~-10.78, ~-0.237 ]
* // D => <Float64Array>[ ~-4.822, ~-10.78 ]
* // E => <Float64Array>[ ~-3.007 ]
* // TAUQ => <Float64Array>[ ~1.83, ~1.894 ]
* // TAUP => <Float64Array>[ 0.0, 0.0 ]
* // WORK[ 0 ] => 3.0
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var dgebrd;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dgebrd = main;
} else {
	dgebrd = tmp;
}


// EXPORTS //

module.exports = dgebrd;

// exports: { "ndarray": "dgebrd.ndarray" }
